  'tool3-pro2' => 'Աշխատում է հեռախոսների, պլանշետների կամ համակարգիչների բրաուզերների մեծ մասում',
  'tool3-pro3' => 'Առաջարկում է բազմաթիվ ուղեկից գործիքներ, ինչպիսիք են PDF ֆայլերը բաժանելը և սեղմելը',
  'tool3-con1' => 'Շատ մեծ միաձուլումները կարող են պահանջել պրեմիում հաշիվ',
  'tool3-con2' => 'Համացանցը պետք է միացված մնա միաձուլման գործընթացում',
  'tool3-con3' => 'Որոշ գործառույթներ պահանջում են մուտք գործել նախքան օգտագործումը',
  'comparison-intro' => 'Եկեք համառոտ համեմատենք վերը նշված գործիքները:',
  'table-feature' => 'Առանձնահատկություն',
