  'table-row1-adobe' => 'Միայն հիմնական անվճար առցանց',
  'table-row1-ilovepdf' => 'Այո հիմնական գործառույթներն անվճար են',
  'table-row2-feature' => 'Անցանց տարբերակ',
  'table-row2-smallpdf' => 'Սահմանափակ',
  'table-row2-adobe' => 'Ամբողջական աշխատասեղան հասանելի է',
  'table-row2-ilovepdf' => 'Սեղանի հավելվածը գոյություն ունի',
  'table-row3-feature' => 'Էջի վերադասավորում',
